#!/usr/bin/env bash
source "$(dirname "$0")/common.sh" "$@"
need WORKER_URL
ENV_VARS="APP_ENV=production,AUTO_CREATE_SCHEMA=false,ANALYSIS_QUEUE_BACKEND=cloud_tasks,GCP_PROJECT_ID=$GCP_PROJECT_ID,GCP_REGION=$GCP_REGION,CLOUD_TASKS_QUEUE=$CLOUD_TASKS_QUEUE,ANALYSIS_WORKER_URL=$WORKER_URL,CLOUD_TASKS_OIDC_AUDIENCE=$WORKER_URL,CLOUD_TASKS_SERVICE_ACCOUNT_EMAIL=$TASKS_INVOKER_SERVICE_ACCOUNT_EMAIL,DATABASE_HOST=/cloudsql/$CLOUD_SQL_CONNECTION_NAME,DATABASE_NAME=$CLOUD_SQL_DATABASE,DATABASE_USER=$CLOUD_SQL_USER,DB_POOL_SIZE=2,DB_MAX_OVERFLOW=1,SCHEDULED_SYNC_ENABLED=true,STOCKFISH_PATH=/usr/games/stockfish"
run gcloud run deploy "$SYNC_SERVICE" --project "$GCP_PROJECT_ID" --region "$GCP_REGION" --image "$BACKEND_IMAGE" --service-account "$BACKEND_SERVICE_ACCOUNT_EMAIL" --set-cloudsql-instances "$CLOUD_SQL_CONNECTION_NAME" --set-env-vars "$ENV_VARS" --set-secrets "DATABASE_PASSWORD=DATABASE_PASSWORD:latest,CHESSCOM_USER_AGENT=CHESSCOM_USER_AGENT:latest,ANALYSIS_WORKER_SHARED_SECRET=ANALYSIS_WORKER_SHARED_SECRET:latest,SCHEDULED_SYNC_SHARED_SECRET=SCHEDULED_SYNC_SHARED_SECRET:latest" --port 8080 --timeout 300 --concurrency 1 --cpu 1 --memory 1Gi --min-instances 0 --max-instances 1 --no-allow-unauthenticated --quiet
run gcloud run services add-iam-policy-binding "$SYNC_SERVICE" --project "$GCP_PROJECT_ID" --region "$GCP_REGION" --member "serviceAccount:$SCHEDULER_SERVICE_ACCOUNT_EMAIL" --role roles/run.invoker --quiet
if $APPLY; then echo "SYNC_SERVICE_URL=$(gcloud run services describe "$SYNC_SERVICE" --project "$GCP_PROJECT_ID" --region "$GCP_REGION" --format='value(status.url)')"; fi
